<!--vbase-->
<template>
  <q-card flat bordered class="import-container white-back">
    <q-card-section>
      <div class="row">
        <q-space />
        <f-btn @click="formatCode" :label="$t('format_button')" />
        <f-btn @click="saveRecord" :label="$t('save')" class="q-ml-sm" />
      </div>
    </q-card-section>
    <q-card-section class="row items-center q-pb-md editor-height">
      <editor :formatCode="is_format_code" @formatComplete="afterFormatted" />
    </q-card-section>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import editor from 'src/pages/Settings/Components/XSLT/editor.vue';
// import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin';
import { useDocXsltStore } from 'src/store/main';
import { ApiExceptions } from 'src/exceptions';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: {},
  components: {
    editor,
  },
  watch: {
    processing: {
      handler: function (newVal, oldVal) {
        if (newVal === false) {
          this.hideLoading();
        } else {
          this.showLoading();
        }
      },
    },
  },
  data() {
    return {
      title: '',
      is_format_code: ref(false),
    };
  },
  mounted() {
    const title = this.$route.query.title?.toString();
    if (title) {
      this.title = title;
    }
  },
  methods: {
    async saveRecord() {
      const isValid = await this.formRef?.validate();
      if (!isValid) {
        return;
      }
      try {
        this.processing = true;
        const response = await this.createExtractionAttribute();
        if (response) {
          notify.success(this.$t('MSG_SAVE'));
          this.resetRecord();
          this.$router.push(
            `/settings/manage-xslt/${String(response.data.doc_type_key)}/${String(response.data.id)}/${String(response.data.electronic_document_type)}?title=${this.title}`,
          );
        }
        this.processing = false;
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error);
        notify.error(msg);
        this.processing = false;
      }
    },
    formatCode() {
      this.is_format_code = true;
    },
    afterFormatted(value: any) {
      this.is_format_code = value;
    },
    resetRecord() {
      this.formRef?.reset();
      this.resetCurrentModel();
      this.current_model.doc_type = this.$route.params.doc_type;
      this.current_model.e_doc_type = this.$route.params.e_doc_type;
      this.current_model.doc_type_key = this.$route.params.doc_type;
    },
  },
  setup() {
    const xslt_store = useDocXsltStore();
    const { processing, formRef, current_model } = storeToRefs(xslt_store);
    const { createExtractionAttribute, resetCurrentModel } = xslt_store;
    return {
      formRef,
      processing,
      createExtractionAttribute,
      resetCurrentModel,
      current_model,
    };
  },
});
</script>

