<template>
  <div class="col-4 secondary-c-text text-h6">
    <q-btn
      flat
      rounded
      data-cy="dashboard"
      color="primary"
      :to="`/settings/manage-xslt/${$route.params.doc_type}?tab=${$route.params.e_doc_type}&title=${title}`"
    >
      <Icon icon="mdi:arrow-left-circle" width="20" height="20" />
      <label
        style="
          vertical-align: middle;
          margin-left: 10px;
          font-size: 20px;
          cursor: pointer;
        "
        >{{ $t('document_types') }}</label
      >
    </q-btn>
  </div>
  <q-form ref="formRef">
    <div class="row">
      <div class="col-3 q-pa-sm">
        <div class="q-ma-md">
          <q-select
            hide-dropdown-icon
            outlined
            disable
            readonly
            v-model="current_model.doc_type"
            use-input
            v-bind:options="doc_type_list"
            :label="$t('document_type')"
            @filter="filterDocTypeListEvent"
            :loading="doc_type_loading"
            emit-value
            map-options
            dense
            class="back-white"
          >
          </q-select>
        </div>
        <div class="q-ma-md">
          <q-select
            hide-dropdown-icon
            outlined
            disable
            readonly
            v-model="current_model.e_doc_type"
            use-input
            v-bind:options="e_document_types"
            :label="$t('e_document_type')"
            @filter="filterDocTypeListEvent"
            :loading="doc_type_loading"
            emit-value
            map-options
            dense
            class="back-white"
          >
          </q-select>
        </div>
        <div class="q-ma-md">
          <q-select
            outlined
            v-model="current_model.attribute_name"
            v-bind:options="attribute_names"
            @filter="filterDocTypeListEvent"
            :loading="doc_type_loading"
            emit-value
            map-options
            dense
            labelSlot
            hideBottomSpace
            :rules="[(val: any) => !!val || 'Field is required']"
          >
            <template v-slot:label>
              {{ $t('attribute_name') }} <span class="text-red">&nbsp;*</span>
            </template>
          </q-select>
        </div>
        <div class="q-ma-md">
          <q-select
            outlined
            disable
            hide-dropdown-icon
            v-model="current_model.attribute_type"
            use-input
            readonly
            v-bind:options="attribute_types"
            @filter="filterDocTypeListEvent"
            :loading="doc_type_loading"
            emit-value
            map-options
            dense
            labelSlot
            hideBottomSpace
            :rules="[(val: any) => !!val || 'Field is required']"
          >
            <template v-slot:label>
              {{ $t('attribute_type') }} <span class="text-red">&nbsp;*</span>
            </template>
          </q-select>
        </div>
      </div>
      <div class="col-9">
        <editor />
      </div>
    </div>
  </q-form>
  <div class="loading-component" v-if="processing">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </div>
</template>
<script lang="ts">

import { defineComponent, ref } from 'vue';
import editor from 'src/pages/Settings/Components/XSLT/add-editor.vue';
import { useDocXsltStore, useDropdownStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin';
import { storeToRefs } from 'pinia';
import { ApiExceptions } from 'src/exceptions';
import {
  attribute_types,
  attribute_names,
  e_document_types,
} from 'src/constants';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  components: {
    
    editor,
  },
  data() {
    return {
      title: '',
    };
  },
  mounted() {
    this.init();
    const title = this.$route.query.title?.toString();
    if (title) {
      this.title = title;
    }
  },
  watch: {
    attribute_name: {
      handler: function (newVal, oldVal) {
        if (newVal != oldVal.attribute_name) {
          if (newVal == 'STRUCTURE_DESCRIPTOR') {
            this.current_model.attribute_type = 'JSON';
          }
          if (newVal == 'TRANSFORMATION') {
            this.current_model.attribute_type = 'XSLT';
          }
          if (newVal == 'EXTRACTION_PATHS') {
            this.current_model.attribute_type = 'JSON';
          }
          if (newVal == 'PREVIEW') {
            this.current_model.attribute_type = 'XSLT';
          }
        }
      },
    },
  },

  computed: {
    attribute_name() {
      return this.current_model.attribute_name as string;
    },
  },
  methods: {
    init() {
      this.processing = true;
      this.current_model.doc_type = this.$route.params.doc_type;
      this.current_model.e_doc_type = this.$route.params.e_doc_type;
      this.current_model.doc_type_key = this.$route.params.doc_type;
      setTimeout(() => {
        this.processing = false;
      }, 2000);
    },
  },
  setup() {
    const dropdown_store = useDropdownStore();
    const xslt_store = useDocXsltStore();
    const { current_model, processing, formRef } = storeToRefs(xslt_store);
    const { doc_type_list } = storeToRefs(dropdown_store);
    return {
      formRef,
      doc_type_list,
      current_model,
      processing,
      filterDocTypeListEvent: (val: string, update: any) => {
        // Filter logic
      },
      doc_type_loading: ref(false),
      attribute_types,
      attribute_names,
      e_document_types,
    };
  },
});
</script>
